begin;
set local search_path=public,extensions;
select set_config('storage.allow_delete_query','true',true);
select no_plan();
-- business dm fixtures
insert into public.conversations(id,kind,user_low_id,business_high_id,status) values
  ('b1930000-0000-4000-8000-000000000001','business','b1900000-0000-4000-8000-000000000003','b1910000-0000-4000-8000-000000000001','active');
select set_config('test.chat_path','b1910000-0000-4000-8000-000000000001/b1930000-0000-4000-8000-000000000001_1792280000000-AbCd123.webp',true);
select set_config('test.unsent_path','b1910000-0000-4000-8000-000000000001/b1930000-0000-4000-8000-000000000001_1792280000001-Zyx987.webp',true);
select set_config('request.jwt.claims','{"sub":"b1900000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select set_config('storage.operation','storage.object.upload',true);
set local role authenticated;
select lives_ok($$insert into storage.objects(bucket_id,name,owner_id) values('chat-images',current_setting('test.chat_path'),auth.uid()::text)$$,'current operator can upload actor-free Date.now key');
select lives_ok($$insert into storage.objects(bucket_id,name,owner_id) values('chat-images',current_setting('test.unsent_path'),auth.uid()::text)$$,'current endpoint can stage another photo');
select throws_ok($$insert into storage.objects(bucket_id,name,owner_id) values('chat-images','b1900000-0000-4000-8000-000000000002/b1930000-0000-4000-8000-000000000001_1792280000002-Bad.webp',auth.uid()::text)$$,'42501',null,'business upload cannot use private actor prefix');
select public.send_business_chat_message('b1930000-0000-4000-8000-000000000001','b1910000-0000-4000-8000-000000000001','b1940000-0000-4000-8000-000000000001',p_kind=>'image',p_image_paths=>array[current_setting('test.chat_path')]);
select set_config('storage.operation','storage.object.sign_upload_url',true);
select throws_ok($$insert into storage.objects(bucket_id,name,owner_id) values('chat-images','b1910000-0000-4000-8000-000000000001/b1930000-0000-4000-8000-000000000001_1792280000004-Signed.webp',auth.uid()::text)$$,'42501',null,'signed upload permission cannot outlive current endpoint authorization');
select set_config('storage.operation','',true);
select is((select count(*) from storage.objects where name=current_setting('test.chat_path')),0::bigint,'raw storage metadata is hidden even from uploader');
select set_config('storage.operation','storage.object.sign',true);
select is((select count(*) from storage.objects where name=current_setting('test.chat_path')),0::bigint,'signed URL operation cannot read business object');
select set_config('storage.operation','storage.object.sign_many',true);
select is((select count(*) from storage.objects where name=current_setting('test.chat_path')),0::bigint,'batch signing cannot bypass JWT revocation');
select set_config('storage.operation','storage.object.list',true);
select is((select count(*) from storage.objects where name=current_setting('test.chat_path')),0::bigint,'list operation cannot expose owner metadata');
select set_config('storage.operation','storage.object.list_v2',true);
select is((select count(*) from storage.objects where name=current_setting('test.chat_path')),0::bigint,'list v2 cannot expose owner metadata');
select set_config('storage.operation','object.get_authenticated_info',true);
select is((select count(*) from storage.objects where name=current_setting('test.chat_path')),0::bigint,'object info cannot expose uploader identity');
select set_config('storage.operation','storage.object.get_authenticated',true);
select is((select count(*) from storage.objects where name=current_setting('test.chat_path')),1::bigint,'current JWT authenticated download is allowed');
reset role;
select set_config('request.jwt.claims','{"sub":"b1900000-0000-4000-8000-000000000003","role":"authenticated"}',true);
set local role authenticated;
select is((select count(*) from storage.objects where name=current_setting('test.chat_path')),1::bigint,'personal peer can download sent business image');
select is((select count(*) from storage.objects where name=current_setting('test.unsent_path')),0::bigint,'peer cannot download another endpoint staged image');
reset role;
delete from private.merchant_operators where merchant_id='b1910000-0000-4000-8000-000000000001' and user_id='b1900000-0000-4000-8000-000000000002';
select set_config('request.jwt.claims','{"sub":"b1900000-0000-4000-8000-000000000002","role":"authenticated"}',true);
set local role authenticated;
select is((select count(*) from storage.objects where name=current_setting('test.chat_path')),0::bigint,'revoked real uploader loses authenticated image access');
select is((select count(*) from storage.objects where name=current_setting('test.unsent_path')),0::bigint,'revoked uploader loses staged image access');
select set_config('storage.operation','storage.object.delete_many',true);
delete from storage.objects where name=current_setting('test.unsent_path');
reset role;
select ok(exists(select 1 from storage.objects where name=current_setting('test.unsent_path')),'legacy uploader delete policy cannot bypass revoked endpoint');
set local role authenticated;
select throws_ok($$insert into storage.objects(bucket_id,name,owner_id) values('chat-images','b1910000-0000-4000-8000-000000000001/b1930000-0000-4000-8000-000000000001_1792280000003-Revoked.webp',auth.uid()::text)$$,'42501',null,'revoked role cannot stage another image');
reset role;
select set_config('request.jwt.claims','{"sub":"b1900000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select set_config('storage.operation','storage.object.get_authenticated',true);
set local role authenticated;
select is((select count(*) from storage.objects where name=current_setting('test.chat_path')),1::bigint,'current owner retains sent business media');
reset role;
select set_config('request.jwt.claims','{"sub":"b1900000-0000-4000-8000-000000000004","role":"authenticated","aal":"aal2","session_id":"b1990000-0000-4000-8000-000000000004","app_metadata":{"role":"admin"}}',true);
set local role authenticated;
select is((select count(*) from storage.objects where name=current_setting('test.chat_path')),1::bigint,'AAL2 admin authenticated GET can review business image');
reset role;
select ok(exists(select 1 from public.admin_access_logs where actor_id='b1900000-0000-4000-8000-000000000004' and scope='messages'
  and resource_id in(select id from public.messages where image_path=current_setting('test.chat_path'))),'business image admin read writes attributable audit entry');
insert into public.conversations(id,user_low_id,user_high_id,status) values
 ('b1930000-0000-4000-8000-000000000002','b1900000-0000-4000-8000-000000000002','b1900000-0000-4000-8000-000000000003','active');
insert into storage.objects(bucket_id,name,owner_id) values('chat-images','b1900000-0000-4000-8000-000000000002/b1930000-0000-4000-8000-000000000002_legacy.webp','b1900000-0000-4000-8000-000000000002');
select set_config('request.jwt.claims','{"sub":"b1900000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select set_config('storage.operation','',true);
set local role authenticated;
select is((select count(*) from storage.objects where name='b1900000-0000-4000-8000-000000000002/b1930000-0000-4000-8000-000000000002_legacy.webp'),1::bigint,'existing personal bucket owner behavior remains unchanged');
reset role;
select * from finish();
rollback;
